use serde_json::{json,Value};
use sha2::{Digest,Sha256};
use std::{collections::{BTreeMap,BTreeSet},fs,io::Read,path::Path};
fn read(p:impl AsRef<Path>)->Value{serde_json::from_slice(&fs::read(p).unwrap()).unwrap()}
fn hash(p:impl AsRef<Path>)->String{let mut f=fs::File::open(p).unwrap();let mut h=Sha256::new();let mut b=[0;65536];loop{let n=f.read(&mut b).unwrap();if n==0{break}h.update(&b[..n]);}format!("{:x}",h.finalize())}
fn check(dir:&Path){let v=read(dir.join("exit.json"));assert_eq!(v["success"],true);assert_eq!(v["returncode"],0);for stream in ["stdout","stderr"]{assert_eq!(hash(dir.join(format!("{stream}.log"))),v[format!("{stream}_sha256")].as_str().unwrap());}}
fn suite(dir:&Path,passed:usize,ignored:usize){check(dir);let text=fs::read_to_string(dir.join("stdout.log")).unwrap();let mut total=0;let mut skips=0;let mut count=0;for line in text.lines().filter(|l|l.starts_with("test result: ok.")){let words=line.split_whitespace().collect::<Vec<_>>();total+=words[3].parse::<usize>().unwrap();assert_eq!(words[5],"0");skips+=words[7].parse::<usize>().unwrap();assert_eq!(words[11],"0");count+=1;}assert!(count>0);assert_eq!(total,passed);assert_eq!(skips,ignored);}
fn workflow(root:&Path,count:usize){let result=read(root.join("result.json"));assert_eq!(result["status"],"complete");assert_eq!(result["steps"].as_array().unwrap().len(),count);for name in result["steps"].as_array().unwrap(){let name=name.as_str().unwrap();let dir=root.join(name);check(&dir);if name.ends_with("-verify"){assert!(fs::read_to_string(dir.join("stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));}}}
fn main(){let root=Path::new("/tmp/zopro-outlined-snapshot-fence");workflow(&root.join("native"),11);workflow(&root.join("preflight"),38);suite(&root.join("native/ordering-model"),5,0);for mode in ["off","on"]{suite(&root.join("native").join(format!("deque-{mode}")),44,0);suite(&root.join("native").join(format!("rayon-{mode}")),113,2);suite(&root.join("native").join(format!("core-{mode}")),109,0);}suite(&root.join("native/prover"),8,0);for name in ["source-audit.json","outline-audit.json","codegen-gate.json","preflight-validation.json"]{assert_eq!(read(root.join(name))["status"],"passed");}
let config=read(root.join("perf-plan.json"));assert_eq!(config["blocks"],7);assert_eq!(config["monotonic_clock"],true);let result=read(root.join("perf/result.json"));assert_eq!(result["status"],"complete");assert_eq!(result["distinct_verified_exports"],292);let rows=read(root.join("perf/rows.json"));assert_eq!(rows.as_array().unwrap().len(),292);let mut sdk=0usize;let mut latency=0;let mut profiles=0;let mut samples=0u64;let mut profile_started=false;let mut profile_ids=BTreeSet::new();let expected_profiles=config["profile_cases"].as_array().unwrap().iter().flat_map(|c|config["variants"].as_array().unwrap().iter().map(move|v|(c.as_str().unwrap().to_owned(),v["name"].as_str().unwrap().to_owned()))).collect::<BTreeSet<_>>();
for r in rows.as_array().unwrap(){let phase=r["phase"].as_str().unwrap();let name=r["case"].as_str().unwrap();let variant=r["variant"].as_str().unwrap();let block=r["block"].as_u64().unwrap();let dir=root.join("perf").join(phase).join(format!("b{block}")).join(name).join(variant);check(&dir.join("run"));check(&dir.join("verify"));assert!(fs::read_to_string(dir.join("verify/stdout.log")).unwrap().contains("verified 1 distinct proofs across 1 pinned keys"));assert_eq!(r["summary"]["priming"],3);assert_eq!(r["summary"]["workers"],if name=="1x2-w16"{16}else{32});sdk+=r["samples_ms"].as_array().unwrap().len()+3;if phase=="profile"{profile_started=true;assert_eq!(block,0);assert!(profile_ids.insert((name.to_owned(),variant.to_owned())));let spec=config["cases"].as_array().unwrap().iter().find(|c|c["name"]==name).unwrap();assert_eq!(r["samples_ms"].as_array().unwrap().len()as u64,spec["profile_rounds"].as_u64().unwrap());check(&dir.join("symbols"));assert_eq!(r["profile"]["lost_records"],0);assert_eq!(r["profile"]["sampled_pids"].as_array().unwrap().len(),1);samples+=r["profile"]["samples"].as_u64().unwrap();profiles+=1;}else{assert_eq!(phase,"latency");assert!(!profile_started);latency+=1;}}
assert_eq!(sdk,12160);assert_eq!(latency,280);assert_eq!(profiles,12);assert_eq!(profile_ids,expected_profiles);
let template=read(root.join("all-nine-template.json"));let fixtures:BTreeMap<String,String>=template["cases"].as_array().unwrap().iter().map(|c|(Path::new(c["image"].as_str().unwrap()).file_stem().unwrap().to_str().unwrap().into(),c["public_sha256"].as_str().unwrap().into())).collect();let prior:BTreeSet<String>=serde_json::from_value(template["prior_proof_sha256"].clone()).unwrap();assert_eq!(prior.len(),3774);let mut inventory=BTreeMap::<String,String>::new();for(name,digest)in read(root.join("preflight-proof-inventory.json")).as_object().unwrap(){assert_eq!(hash(name),digest.as_str().unwrap());assert!(inventory.insert(name.clone(),digest.as_str().unwrap().into()).is_none());}for(name,digest)in read(root.join("perf/proof-inventory.json")).as_object().unwrap(){let path=root.join("perf").join(name);assert_eq!(hash(&path),digest.as_str().unwrap());assert!(inventory.insert(path.to_str().unwrap().into(),digest.as_str().unwrap().into()).is_none());}assert_eq!(inventory.len(),620);
let mut unique=BTreeSet::new();for(name,digest)in &inventory{let p=Path::new(name);if p.extension().is_some_and(|e|e=="proof"){assert_eq!(fs::metadata(p).unwrap().len(),164);assert!(!prior.contains(digest));assert!(unique.insert(digest.clone()));assert!(inventory.contains_key(p.with_extension("public").to_str().unwrap()));}else{assert_eq!(p.extension().unwrap(),"public");let stem=p.parent().unwrap().file_name().unwrap().to_str().unwrap();assert_eq!(&fixtures[stem],digest);}}assert_eq!(unique.len(),310);
let pilot=read(root.join("pilot-result.json"));let passed=pilot["performance_gate_passed"].as_bool().unwrap();let out=json!({"status":if passed{"closed; local speed gate passed, further universal/resource/target qualification outstanding"}else{"closed; fixed all-nine speed gate failed"},"performance_gate_passed":passed,"adopted":false,"goal_achieved":false,"sdk_requests":sdk+72,"distinct_gnark_exports":unique.len(),"proof_public_members":inventory.len(),"profiles":profiles,"profile_samples":samples,"lost_records":0,"models":5,"model_preemption_bound":3,"model_scope":"Modified common-fence ordering/control only. Atomic slots, fixed indices/two generations retained. Not generic volatile payload protocol, epoch collector or full scheduler verification.","crossbeam_each_mode":44,"rayon_each_mode":113,"rayon_ignored_each_mode":2,"core_each_mode":109,"raw_tests":2,"cubic_tests":6,"field_tests":"unchanged kernels; inherited33, not newly run","source_pins":read(root.join("candidate/.xtask/source-pins.json")).as_object().unwrap().len(),"performance_pins":config["pins"].as_object().unwrap().len(),"prior_identities_before_preflight":prior.len(),"failed_checks":pilot["failed_checks"],"original8_aggregate":pilot["original8_aggregate"],"source_audit":read(root.join("source-audit.json")),"outline_audit":read(root.join("outline-audit.json")),"codegen_gate":read(root.join("codegen-gate.json")),"direct_inlined_control":"Frozen previous prototype ON, source/actual binary/libraries pinned; former negative remains negative","all_declared_profile_tuples_checked":true,"decision":if passed{"Preserve positive local candidate; qualify portability/concurrentSDK/resource/pressure/very-large/target behavior before clean production integration."}else{"Do not adopt or rerun unchanged; preserve full data and source, use profiles to select a distinct next hypothesis."},"limits":"No new pressure, portable, concurrent SDK, very-large-circuit, C7a or Aeglos qualification/comparison. Whole-process RSS includes load/primes and is not minimum RAM. Sample-category shares are not removable wall time. M5 values are supplied historical CPU/Metal references, not new matched M5 runs. Full all-eight tenfold goal remains unmet.","owned_aws_resources":0});for(name,value)in [("closeout.json",out),("proof-inventory.json",json!(inventory))]{fs::write(root.join(name),format!("{}\n",serde_json::to_string_pretty(&value).unwrap())).unwrap();}println!("CLOSED_VERIFIED SDK{} EXPORTS310 MEMBERS620 PROFILES12 SAMPLES{samples}",sdk+72);}
